-- 0006_seed_items_and_aliases.sql  (data migration, idempotent)
-- Maps existing receipt line items to a canonical item catalog.
-- Non-destructive: only inserts catalog rows + fills the nullable FK.

on conflict (id) do update set name=excluded.name, unit=excluded.unit, kind=excluded.kind, is_active=true;

on conflict (location_id, norm) do update set inventory_item_id=excluded.inventory_item_id;

update expense_line_items li
set inventory_item_id = a.inventory_item_id
from item_aliases a
where a.location_id = (select location_id from expenses e where e.id = li.expense_id)
  and regexp_replace(lower(btrim(li.description)), '\s+', ' ', 'g') = a.norm
  and li.inventory_item_id is distinct from a.inventory_item_id;